`,e.jsxs(t.li,{children:[e.jsx(t.strong,{children:"Persistence is not an artifact snapshot."})," Datasets are non-persistent by default; ",e.jsx(t.code,{children:"persistent=True"})," retains database records, while raw media remains in external files. Saved views retain selection rules and can change when the underlying records change. Keep original files/hashes and a materialized result manifest separately from a named view. ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/docs/source/user_guide/using_datasets.rst#L139-L157",children:"Dataset persistence"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/docs/source/user_guide/using_views.rst#L187-L196",children:"saved-view semantics"})]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.strong,{children:"Video → frame."})," ",e.jsx(t.code,{children:"to_frames()"})," retains parent-video ",e.jsx(t.code,{children:"sample_id"})," and ",e.jsx(t.strong,{children:"1-based"})," ",e.jsx(t.code,{children:"frame_number"}),"; the implementation reuses source frame IDs. Without sampling, frames lacking ",e.jsx(t.code,{children:"filepath"})," are omitted. ",e.jsx(t.code,{children:"sample_frames=True"})," writes images and source frame paths, and normally reuses existing sampled images unless ",e.jsx(t.code,{children:"force_sample=True"}),". FPS selection operates on frame numbers; these inspected interfaces do not establish original presentation timestamps or engine ticks. Preserve the recording hash, explicit frame-to-PTS/tick mapping, sampling/resize parameters and derivative hash; a reused path is not proof of fresh pixels. ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/fiftyone/core/video.py#L528-L648",children:"Frame construction and sampling"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/fiftyone/core/video.py#L944-L978",children:"source frame identity"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/docs/source/user_guide/using_datasets.rst#L5139-L5147",children:"1-based convention"})]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.strong,{children:"Frame → patch."})," Chaining ",e.jsx(t.code,{children:"to_frames().to_patches(field)"})," yields parent-video ",e.jsx(t.code,{children:"sample_id"}),", ",e.jsx(t.code,{children:"frame_id"})," and ",e.jsx(t.code,{children:"frame_number"}),". The patch ID is the source ",e.jsx(t.strong,{children:"label ID"}),", while ",e.jsx(t.code,{children:"filepath"})," remains the full-frame path: this view does not itself establish a separately saved crop. ",e.jsx(t.code,{children:"Detection.bounding_box"})," is normalized ",e.jsx(t.code,{children:"[x,y,width,height]"}),", unlike OmniParser's normalized corner coordinates. Actual crop extraction can expand/square boxes; preserve those parameters and the crop-to-original transform. IDs identify records, not immutable pixel content; retain additional provenance via ",e.jsx(t.code,{children:"other_fields"})," or explicit parent joins. ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/fiftyone/core/patches.py#L936-L988",children:"Patch projection/IDs"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/fiftyone/core/labels.py#L450-L459",children:"box contract"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/fiftyone/utils/patches.py#L160-L189",children:"crop operations"})]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.strong,{children:"Views can write back."})," Editing patch labels and certain frame fields, or calling view ",e.jsx(t.code,{children:"save"}),"/",e.jsx(t.code,{children:"keep"}),"/",e.jsx(t.code,{children:"keep_fields"}),", can modify/delete underlying annotations. Patch sample tags and unrelated sample fields have different propagation rules; frame tags/metadata do not propagate. Treat evidence browsing and annotation edits as different operations. ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/docs/source/user_guide/using_views.rst#L1162-L1197",children:"Patch propagation"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/docs/source/user_guide/using_views.rst#L1888-L1919",children:"frame propagation"})]}),`
`]}),`
`,e.jsx(t.h3,{id:"similarity-freshness-and-result-provenance",children:"Similarity freshness and result provenance"}),`
`,e.jsxs(t.p,{children:["Search within a view only returns indexed members; unindexed captures cannot appear. Index membership and current annotations/media therefore need independent checks. Explicit ",e.jsx(t.code,{children:"add_to_index"}),"/",e.jsx(t.code,{children:"remove_from_index"})," operations manage vectors, and the pinned guide instructs sklearn users to call ",e.jsx(t.code,{children:"save()"})," after those edits. This guidance should not be read as saying every backend path defers all writes: sklearn with ",e.jsx(t.code,{children:"embeddings_field"})," configured writes added embeddings directly. Brain's base ",e.jsx(t.code,{children:"reload()"})," refreshes view IDs; sklearn can reload stored embeddings, but neither inspected reload path recomputes embeddings from changed pixels/boxes. ",e.jsx(t.code,{children:"missing_size=None"})," can mean unsupported/unknown, not confirmed completeness. ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/docs/source/user_guide/similarity.rst#L154-L164",children:"Membership"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone-brain/blob/ba978a12293fda9953b478f601ac8950d2a35aa4/fiftyone/brain/similarity.py#L515-L525",children:"missing-size caveat"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/docs/source/user_guide/similarity.rst#L760-L767",children:"manual save"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone-brain/blob/ba978a12293fda9953b478f601ac8950d2a35aa4/fiftyone/brain/similarity.py#L613-L719",children:"view/reload contract"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone-brain/blob/ba978a12293fda9953b478f601ac8950d2a35aa4/fiftyone/brain/internal/core/sklearn.py#L327-L340",children:"sklearn reload"})]}),`
`,e.jsxs(t.p,{children:["The inspected ",e.jsx(t.code,{children:"SimilarityIndex.sort_by_similarity(..., dist_field=...)"})," path ",e.jsx(t.strong,{children:"writes"})," distances into collection fields or label fields, depending on the sample/patch-view route; it does not merely return a score array. Reusing that field is not an immutable query history. Store each query's ordered IDs and scores separately, with ",e.jsx(t.code,{children:"brain_key"}),", index/membership revision, embedding model/preprocessing, metric/backend, query type and IDs/text/vector hash, candidate-view rules, ",e.jsx(t.code,{children:"k"}),", direction and multi-query aggregation. ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone-brain/blob/ba978a12293fda9953b478f601ac8950d2a35aa4/fiftyone/brain/similarity.py#L756-L865",children:"Distance writes and ordered results"})]}),`
`,e.jsx(t.h3,{id:"localremote-and-rights-boundary",children:"Local/remote and rights boundary"}),`
`,e.jsxs(t.p,{children:["The builtin sklearn backend accepts precomputed embeddings and requires no remote vector service. This does not certify an entirely offline deployment: database endpoints, models and plugins are separate choices, and UUID-based App usage telemetry is enabled by default (",e.jsx(t.code,{children:"do_not_track"})," disables it). Qdrant is optional and may be local or remote; the inspected adapter sends ",e.jsx(t.strong,{children:"vectors, sample/label-derived point IDs and sample-ID payloads"})," to its configured endpoint, and sends query vectors/ID filters during search. These methods do not upload raw frame images; other model/media integrations require separate review. ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/docs/source/user_guide/similarity.rst#L30-L63",children:"Backend/input choices"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone-brain/blob/ba978a12293fda9953b478f601ac8950d2a35aa4/fiftyone/brain/internal/core/qdrant.py#L302-L375",children:"Qdrant upload"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone-brain/blob/ba978a12293fda9953b478f601ac8950d2a35aa4/fiftyone/brain/internal/core/qdrant.py#L550-L609",children:"Qdrant query"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/docs/source/faq/index.rst#L671-L684",children:"telemetry"})]}),`
`,e.jsxs(t.p,{children:["Both inspected code repositories declare Apache-2.0; this does not license source game captures, optional model weights or service use. ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone/blob/aacfc8182fc5353296b5edd7475e63335fedb5cb/LICENSE",children:"FiftyOne license"}),", ",e.jsx(t.a,{href:"https://github.com/voxel51/fiftyone-brain/blob/ba978a12293fda9953b478f601ac8950d2a35aa4/LICENSE",children:"Brain license"})]}),`
`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"Proposed GameMap gate, unimplemented:"})," retrieve a known failed HUD/asset region across two build-tagged capture sets; then deliberately change a source image, box and index membership independently. Require correct frame/crop round-trip identity, visible missing/stale results and preserved per-query manifests. Evaluate retrieval coverage separately from diagnosis or successful repair. This would test the storage/retrieval contract, not game-creation gains."]}),`
`,e.jsx(t.h2,{id:"proposed-shared-observation-contract",children:"Proposed shared observation contract"}),`
`,e.jsx(t.p,{children:"Retain source build/run/frame hashes, original timestamps and render boundaries; selection policy/query and every inspected frame; crop/resize/padding transforms; model/config and inferred-success status. Keep raw evidence beside captions/features, reset episode memory, and keep authoritative engine checks distinct from visual inference. First fixture: a briefly enabled button followed by a delayed effect, with transitions independently annotated from the full recording."}),`
